def grad_f(w1, w2):
    return (2 * (w1 - 3), 4 * (w2 - 1))

def check(point, budget, mu):
    g = point[0] + point[1] - budget
    gf = grad_f(*point)
    return {
        'primal feasible': g <= 1e-9,
        'dual feasible': mu >= 0,
        'complementary': abs(mu * g) < 1e-9,
        'stationary': all(abs(gf[k] + mu) < 1e-9 for k in range(2)),
    }

print(all(check((5 / 3, 1 / 3), 2, 8 / 3).values()))   # True : case A
